/**
 * 语言切换器
 *
 * 放页脚而非导航：导航条宽度在德语下会明显变长（德语单词普遍更长），
 * 挤进导航会挤压「Install free」这个唯一 CTA —— CTA 优先级高于语言入口。
 *
 * 🔴 每个语言指向**当前页的对应版本**（不是首页），否则用户从定价页切语言会被丢回首页。
 * 🔴 hreflang 的权威声明在 SEO 组件里；这里只是可见的入口，两者都要有。
 *
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import { useLocation } from '@reach/router';
import { LOCALES, localePath, resolveLocale } from '../../i18n/config';
import './locale-switcher.css';

export default function LocaleSwitcher() {
  // 🔴 用 useLocation 而不是 window.location —— 后者在 SSR 阶段拿不到值，
  //    会让切换器在构建时渲染成英文、hydration 后跳变。
  const { pathname } = useLocation();
  const { locale, basePath } = resolveLocale(pathname || '/');
  const codes = Object.keys(LOCALES);
  // 只有一种语言时不渲染任何东西
  if (codes.length < 2) return null;

  return (
    <div className="locale-switcher">
      <span className="locale-switcher-label">{LOCALES[locale].label}</span>
      <ul className="locale-switcher-list">
        {codes.map((code) => {
          const cfg = LOCALES[code];
          const to = localePath(basePath, code);
          const isCurrent = code === locale;
          return (
            <li key={code}>
              {isCurrent ? (
                // 当前语言用 span 而非 Link：不该链接到自己（且避免重复内容信号）
                <span className="locale-switcher-item locale-switcher-item-current" aria-current="true">
                  {cfg.nativeName}
                </span>
              ) : (
                <Link className="locale-switcher-item" to={to} lang={cfg.htmlLang}>
                  {cfg.nativeName}
                </Link>
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
}
